-- Corporate Upskilling
insert into public.programs (slug, title, audience, duration, summary, highlights, icon, sort_order)
select r.slug, r.title, r.audience, r.duration, r.summary, r.highlights, r.icon, r.sort_order
from jsonb_populate_record(null::public.programs, convert_from(decode('', 'base64'), 'UTF8')::jsonb) r
on conflict (slug) do nothing;

